<template><div><PageHeader title="Documents" description="Manage training materials, learner files and organization documents."><template #actions><button class="btn primary" @click="open=true">↑ Upload document</button></template></PageHeader><div class="grid-2"><div class="card"><div class="card-header"><div><h3>Recent files</h3><span class="section-note">Private organization storage</span></div><input class="input" style="width:180px" placeholder="Search..."></div><div class="card-pad"><div class="notice-list"><div v-for="doc in docs" :key="doc.name" class="notice-item"><div class="course-icon">{{doc.ext}}</div><div class="notice-copy"><strong>{{doc.name}}</strong><p>{{doc.size}} · {{doc.owner}} · {{doc.date}}</p></div><button class="btn secondary small">Download</button></div></div></div></div><div class="card"><div class="card-header"><h3>Storage overview</h3></div><div class="card-pad"><div class="course-bottom-line"><span>Storage used</span><strong>2.4 GB / 10 GB</strong></div><div class="progress"><span style="width:24%"></span></div><div class="info-list" style="margin-top:16px"><div class="info-box"><span>Course materials</span><strong>1.6 GB</strong></div><div class="info-box"><span>Learner docs</span><strong>580 MB</strong></div><div class="info-box"><span>Certificates</span><strong>220 MB</strong></div><div class="info-box"><span>Other</span><strong>40 MB</strong></div></div></div></div></div><Modal :open="open" title="Upload document" description="Private files will be protected by backend authorization" @close="open=false"><div class="empty-state" style="padding:24px 0"><div class="empty-icon">↑</div><h3>Drop files here</h3><p>PDF, DOCX, PPTX and images up to 10 MB in this demo.</p><button class="btn primary" @click="save">Choose files</button></div></Modal></div></template>
<script setup lang="ts">import {ref} from 'vue';import PageHeader from '../components/PageHeader.vue';import Modal from '../components/Modal.vue';import {useToast} from '../composables/useToast';const open=ref(false);const {push}=useToast();const docs=[{name:'Laravel Fundamentals — Course Guide.pdf',ext:'PDF',size:'2.4 MB',owner:'Ahmed Khan',date:'18 Sep'},{name:'Batch 2026-09-A Attendance.xlsx',ext:'XLS',size:'420 KB',owner:'Nibras',date:'18 Sep'},{name:'Certificate Template v2.pdf',ext:'PDF',size:'1.1 MB',owner:'Nibras',date:'16 Sep'},{name:'Application Security Slides.pptx',ext:'PPT',size:'8.2 MB',owner:'Mariam Ali',date:'14 Sep'}];function save(){open.value=false;push('Upload dialog completed. Backend storage endpoint is ready to connect.','info')}</script>
